<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{actualizarManzana,crearManzana,eliminarManzana,listarManzanas,type Manzana,type SectorOption}from'../services/manzanas'
const sectors=ref<SectorOption[]>([]),rows=ref<Manzana[]>([]),sectorId=ref(0),criterion=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<Manzana|null>(null),error=ref(''),success=ref('');const form=reactive({nombre:''});const sector=computed(()=>sectors.value.find(x=>x.id===sectorId.value));
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarManzanas(sectorId.value,criterion.value,p);rows.value=r.data;sectors.value=r.sectores;lastPage.value=r.last_page;total.value=r.total;if(!sectorId.value&&sectors.value.length){sectorId.value=sectors.value[0]!.id;return await load(1)}}catch(e){error.value=msg(e)}finally{loading.value=false}}function open(x?:Manzana){editing.value=x||null;form.nombre=x?.nombre||'';modal.value=true;error.value=''}async function save(){if(!sectorId.value||!form.nombre.trim()){error.value='Seleccione el sector e ingrese el nombre de la manzana.';return}saving.value=true;try{const data={nombre:form.nombre.trim().toUpperCase()};if(editing.value){await actualizarManzana(sectorId.value,editing.value.id,data);success.value='Manzana actualizada correctamente.'}else{await crearManzana(sectorId.value,data);success.value='Manzana registrada correctamente.'}modal.value=false;await load(editing.value?page.value:1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function remove(x:Manzana){if((x.predios_count||0)>0){error.value=`La manzana ${x.nombre} tiene ${x.predios_count} predio(s) asociado(s).`;return}if(!confirm(`¿Eliminar la manzana ${x.nombre}?`))return;try{await eliminarManzana(sectorId.value,x.id);success.value='Manzana eliminada correctamente.';await load(page.value)}catch(e){error.value=msg(e)}}function changeSector(){criterion.value='';load(1)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Manzanas</nav><header class="hero"><div class="mark">MZ</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Manzanas comerciales</h1><p>Organización territorial dependiente de sectores y distritos.</p></div><div class="counter"><b>{{total}}</b><span>manzanas en el sector</span></div><button :disabled="!sectorId" @click="open()">+ Nueva manzana</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Sector comercial<select v-model.number="sectorId" @change="changeSector"><option :value="0">Seleccione un sector</option><option v-for="x in sectors" :key="x.id" :value="x.id">{{x.distrito}} — {{x.nombre}}</option></select></label><label>Buscar manzana<input v-model.trim="criterion" placeholder="Nombre de manzana" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button></section><section v-if="sector" class="context"><span>DISTRITO / SECTOR SELECCIONADO</span><b>{{sector.distrito}} — {{sector.nombre}}</b></section><div v-if="loading" class="empty">Cargando manzanas…</div><div v-else-if="!rows.length" class="empty">No se encontraron manzanas para el sector seleccionado.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="{inactive:!x.estado}"><div class="badge">{{x.nombre}}</div><div><small>MANZANA COMERCIAL</small><h2>{{x.nombre}}</h2><p>{{sector?.distrito}} · Sector {{sector?.nombre}}</p></div><dl><span><b>{{x.predios_count||0}}</b> predios</span><span><b>{{x.conexiones_count||0}}</b> conexiones</span></dl><footer><button @click="open(x)">Editar</button><button class="delete" :disabled="!x.estado" @click="remove(x)">{{x.estado?'Eliminar':'Inactiva'}}</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'ACTUALIZAR MANZANA':'NUEVA MANZANA'}}</small><h2>{{sector?.distrito}} — {{sector?.nombre}}</h2></div><button type="button" @click="modal=false">×</button></header><label>Nombre de la manzana *<input v-model.trim="form.nombre" autofocus placeholder="Ej. A, B, 01"></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar manzana'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#bd812b;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.counter{margin-left:auto;text-align:right}.counter b,.counter span{display:block}.counter b{font-size:.9rem}.counter span{font-size:.43rem}.hero>button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.49rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1.5fr 1fr auto;align-items:end;gap:8px;background:#fff}.filters label,.modal label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.context{padding:9px 13px;border-top:1px solid #eee7db;background:#fff}.context span,.context b{display:block}.context span{color:#9b8b72;font-size:.4rem}.context b{font-size:.55rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:13px;border-top:4px solid var(--a);border-radius:8px;background:#fff}.cards article>div:nth-child(2){display:inline-block;vertical-align:middle}.badge{width:42px;height:42px;margin-right:8px;display:inline-grid!important;place-items:center;border-radius:8px;color:#fff;background:var(--a);font-weight:800}.cards small{color:#9a8769;font-size:.4rem}.cards h2{margin:2px 0;font-size:.72rem}.cards p{margin:0;color:#7f8b90;font-size:.46rem}.cards dl{padding:8px;display:flex;gap:18px;background:#f7f5f1;font-size:.43rem}.cards dl b{color:var(--a);font-size:.62rem}.cards footer{display:flex;gap:5px}.cards footer button{flex:1;padding:7px;border:0;border-radius:4px;color:#fff;background:#687b83;font-size:.44rem}.cards footer .delete{background:#a5484b}.inactive{opacity:.55}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,440px);padding:20px;border-radius:12px;background:#fff}.modal>header{margin-bottom:15px;display:flex}.modal h2{margin:2px 0;font-size:.75rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#64737a!important;background:#edf1f2!important}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.counter{margin-left:0}.filters,.cards{grid-template-columns:1fr}}
</style>
